package com.payguard.payment.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="transactions") public class Transaction { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="transaction_id",nullable=false,unique=true,updatable=false) private String transactionId; @Column(name="merchant_id",nullable=false,updatable=false) private String merchantId; @Column(name="amount_minor",nullable=false) private long amountMinor; @Column(nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(nullable=false) private TransactionStatus status; @Column(name="stripe_charge_id") private String stripeChargeId; @Column(name="fraud_score") private Double fraudScore; @Column(name="fraud_decision") private String fraudDecision; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected Transaction(){} public Transaction(String transactionId,String merchantId,long amountMinor,String currency){this.transactionId=transactionId;this.merchantId=merchantId;this.amountMinor=amountMinor;this.currency=currency;status=TransactionStatus.PENDING;} @PrePersist void created(){createdAt=updatedAt=Instant.now();} @PreUpdate void updated(){updatedAt=Instant.now();} public String getTransactionId(){return transactionId;} public String getMerchantId(){return merchantId;} public long getAmountMinor(){return amountMinor;} public String getCurrency(){return currency;} public TransactionStatus getStatus(){return status;} public String getStripeChargeId(){return stripeChargeId;} public Double getFraudScore(){return fraudScore;} public String getFraudDecision(){return fraudDecision;} public void decision(double score,String value){fraudScore=score;fraudDecision=value;} public void status(TransactionStatus value){status=value;} public void stripeChargeId(String value){stripeChargeId=value;} }
